function applyEmojiPreferences(appearance) {
  document.documentElement.style.setProperty("--ntr-emoji-calories", `'${appearance.caloriesEmoji}'`);
  document.documentElement.style.setProperty("--ntr-emoji-protein", `'${appearance.proteinEmoji}'`);
  document.documentElement.style.setProperty("--ntr-emoji-carbs", `'${appearance.carbsEmoji}'`);
  document.documentElement.style.setProperty("--ntr-emoji-fat", `'${appearance.fatEmoji}'`);
}

// src/utils/meal/migrate-if-needed.ts
var import_obsidian14 = require("obsidian");
async function migrateIfNeeded(vault, settings) {
  const meals = await readMeals(vault, settings);
  const legacyMeals = meals.filter(isLegacyMeal);
  if (legacyMeals.length === 0) {
    return { migrated: false, count: 0 };
  }
  const migratedMeals = migrateMealsToV2(meals);
  await writeMeals(vault, settings, migratedMeals);
  new import_obsidian14.Notice(`\u2705 Migrated ${legacyMeals.length} meal(s) to new format`);
  return { migrated: true, count: legacyMeals.length };
}

